                background-color: #120B24;
            }
            QWidget {
                background-color: #120B24;
                color: #FFFFFF;
                font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            }
            QLabel {
                font-size: 13px;
                color: #E2E8F0;
            }
            QLabel#title {
                font-size: 18px;
                font-weight: bold;
                color: #FFFFFF;
            }
            QLabel#badge {
                font-size: 11px;
                font-weight: bold;
                color: #10B981;
                background-color: #064E3B;
                padding: 2px 8px;
                border-radius: 4px;
            }
            QLineEdit {
                background-color: #1A102F;
                border: 1px solid #2563EB;
                border-radius: 6px;
                padding: 10px 14px;
                color: #FFFFFF;
